mapper.delete:
DELETE FROM diag_result_customer_contribution
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}

mapper.select:
SELECT COUNT(1)
FROM diag_result_customer_contribution
WHERE tenant_id = #{tenantId}
  AND query_hash = #{queryHash}
  AND data_version = #{dataVersion}

SELECT COUNT(1)
FROM (
    SELECT age_bucket_code
    FROM diag_result_customer_contribution
    WHERE tenant_id = #{tenantId}
      AND query_hash = #{queryHash}
      AND data_version = #{dataVersion}
    GROUP BY age_bucket_code
) t
